        raise Blocked("TC-127 前提查询失败：GET /rating-categories 应返回分类编码数组")
    if not all(isinstance(item, str) for item in responseBody["data"]):
        raise Blocked("TC-127 前提查询失败：分类编码数组元素应为字符串")
    assert responseBody.get("requestId")
